// #91: may the fuller internal changelog render on THIS deploy? True on any
// non-production environment. Unknown/unset env is treated as production
// (safe default — never leak internal notes to prod). The changelog view ORs
// this with an admin check so admins always see the detail wherever they are.
export function isNonProdEnv() {
  const env = (process.env.NEXT_PUBLIC_APP_ENV || process.env.NEXT_PUBLIC_VERCEL_ENV || "").toLowerCase();
  return env === "development" || env === "dev" || env === "staging" || env === "preview";
}

// Flatten INTERNAL_CHANGELOG to a { version -> notes[] } lookup for the view.
//
// Several entries may share one version: the pre-3.0.0 dev cycle ran as
// 2.31/2.32/2.33-beta.N and all of it rolled up into the single 3.0.0 release, so those
// entries carry version "3.0.0" plus a `cycle` label recording which beta they came from.
// This MUST concatenate rather than assign — `map[e.version] = e.notes` would silently
// keep only the last entry and drop the other 49 notes. When an entry carries a `cycle`,
// a marker line is emitted ahead of its notes so provenance survives the merge.
export function internalNotesByVersion() {
  const map = {};
  INTERNAL_CHANGELOG.forEach((e) => {
    if (!map[e.version]) map[e.version] = [];
    if (e.cycle) map[e.version].push(`— dev cycle ${e.cycle}${e.date ? ` · ${e.date}` : ""} —`);
    map[e.version].push(...e.notes);
  });
  return map;
}

// Resolve a changelog bullet (string OR { en, es }) to display text for a
// given language, falling back to English. #72 localization.
export function changeText(c, lang) {
  if (typeof c === "string") return c;
  return (c && (c[lang] || c.en)) || "";
}
